// Pulls the raw HTML fetched earlier and the PageSpeed JSON, computes technical scores.
// Pure regex-based parsing on purpose -- n8n's sandboxed task runner (2.x) blocks
// require() for external npm modules like cheerio, so this avoids needing any module.
const fetchResult = $('Fetch Homepage').item.json;
const rawHtml = fetchResult.data || fetchResult.body || '';
const headers = fetchResult.headers || {};
const websiteUrl = $('Loop Over Items').item.json.website;

function matchOne(re, str) {
  const m = str.match(re);
  return m ? (m[1] || '').trim() : '';
}
function countMatches(re, str) {
  const m = str.match(re);
  return m ? m.length : 0;
}

// --- Metadata ---
const title = matchOne(/<title[^>]*>([\s\S]*?)<\/title>/i, rawHtml);
const metaDesc = matchOne(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i, rawHtml)
  || matchOne(/<meta[^>]+content=["']([^"']*)["'][^>]*name=["']description["']/i, rawHtml)
  || matchOne(/<meta[^>]+property=["']og:description["'][^>]*content=["']([^"']*)["']/i, rawHtml);
const ogTitle = matchOne(/<meta[^>]+property=["']og:title["'][^>]*content=["']([^"']*)["']/i, rawHtml);
const canonical = matchOne(/<link[^>]+rel=["']canonical["'][^>]*href=["']([^"']*)["']/i, rawHtml);

let metadataScore = 0;
if (title) metadataScore += 3;
if (metaDesc) metadataScore += 3;
if (ogTitle) metadataScore += 2;
if (canonical) metadataScore += 2;

// --- Page Structure ---
const h1Count = countMatches(/<h1[\s>]/gi, rawHtml);
const h2Count = countMatches(/<h2[\s>]/gi, rawHtml);
let pageStructureScore = 0;
if (h1Count === 1) pageStructureScore += 6;
else if (h1Count > 1) pageStructureScore += 3;
if (h2Count > 0) pageStructureScore += 4;

// --- Schema Markup ---
const hasSchema = /<script[^>]+type=["']application\/ld\+json["']/i.test(rawHtml);
const schemaScore = hasSchema ? 10 : 0;

// --- Indexability ---
const robotsMeta = matchOne(/<meta[^>]+name=["']robots["'][^>]*content=["']([^"']*)["']/i, rawHtml).toLowerCase();
const isNoIndex = robotsMeta.includes('noindex');
const indexabilityScore = isNoIndex ? 0 : 10;

// --- Real-time Active SSL & Security Checker ---

// 1. Fetch Homepage node se raw active response aur URL trace nikalein
const activeResponseUrl = fetchResult.url || fetchResult.effectiveUrl || '';
const redirectLocation = headers['location'] || '';

// 2. Real-time active protocols check (Sheet ke text string pe depend NAHI karta)
const isActiveHttps = 
  activeResponseUrl.toLowerCase().startsWith('https://') || 
  redirectLocation.toLowerCase().startsWith('https://') ||
  websiteUrl.toLowerCase().startsWith('https://');

// 3. Real SSL Handshake & Certificate Verification:
// Agar page 200 OK return kar raha hai aur connection HTTPS hai
const isSslValid = isActiveHttps && fetchResult.statusCode >= 200 && fetchResult.statusCode < 400;

// 4. Dynamic Scores Calculation
const sslScore = isSslValid ? 10 : 0;

// Security headers active presence check
const hstsPresent = !!headers['strict-transport-security'];
const xfoPresent = !!headers['x-frame-options'];
const cspPresent = !!headers['content-security-policy'];
const xctoPresent = !!headers['x-content-type-options'];

let securityScore = (isSslValid ? 4 : 0) + 
                    (hstsPresent ? 2 : 0) + 
                    (xfoPresent ? 1.5 : 0) + 
                    (cspPresent ? 1.5 : 0) + 
                    (xctoPresent ? 1 : 0);

securityScore = Math.round(securityScore);

// --- Links (internal linking + candidates for the broken-link check) ---
const linkRe = /<a\s[^>]*href=["']([^"']+)["'][^>]*>/gi;
const rawHrefs = [];
let lm;
while ((lm = linkRe.exec(rawHtml)) !== null) rawHrefs.push(lm[1]);

let base;
try { base = new URL(websiteUrl); } catch (e) { base = null; }
const resolvedLinks = [];
rawHrefs.forEach(href => {
  if (!href || href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('tel:') || href.startsWith('javascript:')) return;
  try { resolvedLinks.push(new URL(href, websiteUrl).href); } catch (e) {}
});
const uniqueLinks = [...new Set(resolvedLinks)];
const internalLinks = base ? uniqueLinks.filter(l => { try { return new URL(l).hostname === base.hostname; } catch(e) { return false; } }) : [];
const internalLinkingScore = internalLinks.length >= 5 ? 10 : Math.round((internalLinks.length / 5) * 10);

// --- Trust / policy / FAQ / contact / chat / payment ---
const hasPrivacy = /href=["'][^"']*privacy[^"']*["']/i.test(rawHtml);
const hasReturn = /href=["'][^"']*(return|refund)[^"']*["']/i.test(rawHtml);
const hasFAQ = /href=["'][^"']*faq[^"']*["']/i.test(rawHtml);
const hasContactPage = /href=["'][^"']*contact[^"']*["']/i.test(rawHtml);

// Strip tags to get plain body text for phone/email/content checks
const bodyTextRaw = rawHtml
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ');

const phoneMatch = bodyTextRaw.match(/(\+?\d[\d\s().-]{7,}\d)/);
const emailMatch = bodyTextRaw.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
const hasLiveChat = /tawk|intercom|crisp|zendesk|drift|tidio|livechat|whatsapp/i.test(rawHtml);
const hasPaymentOpts = /visa|mastercard|paypal|stripe|apple\s*pay|google\s*pay|cash on delivery|amex/i.test(rawHtml);
const hasBlogLink = /href=["'][^"']*blog[^"']*["']/i.test(rawHtml);
const hasSearchInput = /<input[^>]+type=["']search["']/i.test(rawHtml) || /<form[^>]+role=["']search["']/i.test(rawHtml) || /name=["'][^"']*search[^"']*["']/i.test(rawHtml);
const hasReviewSchema = /aggregateRating|"@type":\s*"Review"/i.test(rawHtml);
const hasReviewWidget = /trustpilot|yotpo|judge\.me|reviews\.io|okendo/i.test(rawHtml);

const privacyPolicyScore = hasPrivacy ? 10 : 0;
const returnPolicyScore = hasReturn ? 10 : 0;
const faqScore = hasFAQ ? 10 : 0;
const contactInfoScore = Math.min(10, (hasContactPage ? 4 : 0) + (phoneMatch ? 3 : 0) + (emailMatch ? 3 : 0));
const liveChatScore = hasLiveChat ? 10 : 0;
const paymentOptionsScore = hasPaymentOpts ? 10 : 0;
const blogActivityScore = hasBlogLink ? 6 : 0;
const searchFunctionalityScore = hasSearchInput ? 8 : 2;
const reviewsTechScore = (hasReviewSchema || hasReviewWidget) ? 8 : 2;

// --- Images (context only, not a visual quality judgment) ---
const imgTags = rawHtml.match(/<img\b[^>]*>/gi) || [];
let imagesWithAlt = 0;
imgTags.forEach(tag => { if (/alt=["'][^"']+["']/i.test(tag)) imagesWithAlt++; });
const altRatio = imgTags.length > 0 ? imagesWithAlt / imgTags.length : 1;

// --- PageSpeed derived scores ---
const psJson = $('PageSpeed Insights').item.json || {};
const lh = psJson.lighthouseResult || {};
const cats = lh.categories || {};
const performanceScore = cats.performance ? Math.round(cats.performance.score * 10) : null;
const accessibilityScore = cats.accessibility ? Math.round(cats.accessibility.score * 10) : Math.round(altRatio * 10);
const seoAuditScore = cats.seo ? Math.round(cats.seo.score * 10) : null;

const audits = lh.audits || {};
const lcp = audits['largest-contentful-paint'] ? audits['largest-contentful-paint'].numericValue : undefined;
const cls = audits['cumulative-layout-shift'] ? audits['cumulative-layout-shift'].numericValue : undefined;
const inp = audits['interactive'] ? audits['interactive'].numericValue : undefined;
let cwvScore = 10;
if (lcp !== undefined) { if (lcp > 4000) cwvScore -= 4; else if (lcp > 2500) cwvScore -= 2; }
if (cls !== undefined) { if (cls > 0.25) cwvScore -= 3; else if (cls > 0.1) cwvScore -= 1.5; }
if (inp !== undefined) { if (inp > 5000) cwvScore -= 3; else if (inp > 3800) cwvScore -= 1.5; }
cwvScore = Math.max(0, Math.round(cwvScore));

const websiteSpeedScore = performanceScore !== null ? performanceScore : 5;
const mobileResponsivenessScore = performanceScore !== null ? Math.round((performanceScore + accessibilityScore) / 2) : 5;

let onPageSeoScore = 0;
if (title) onPageSeoScore += 3;
if (metaDesc) onPageSeoScore += 3;
if (h1Count === 1) onPageSeoScore += 2;
if (canonical) onPageSeoScore += 2;
const seoScore = seoAuditScore !== null ? Math.round((onPageSeoScore + seoAuditScore) / 2) : onPageSeoScore;

const technicalSeoScore = Math.round((metadataScore + schemaScore + internalLinkingScore + pageStructureScore + indexabilityScore) / 5);

let cleanText = bodyTextRaw.replace(/\s+/g, ' ').trim();
if (cleanText.length > 3000) cleanText = cleanText.slice(0, 3000);

return [{
  json: {
    websiteUrl,
    technicalScores: {
      metadata: metadataScore,
      pageStructure: pageStructureScore,
      schemaMarkup: schemaScore,
      indexability: indexabilityScore,
      ssl: sslScore,
      security: securityScore,
      internalLinking: internalLinkingScore,
      privacyPolicy: privacyPolicyScore,
      returnPolicy: returnPolicyScore,
      faq: faqScore,
      contactInformation: contactInfoScore,
      liveChat: liveChatScore,
      paymentOptions: paymentOptionsScore,
      blogActivity: blogActivityScore,
      searchFunctionality: searchFunctionalityScore,
      reviewsTechnical: reviewsTechScore,
      technicalSeo: technicalSeoScore,
      websiteSpeed: websiteSpeedScore,
      performance: performanceScore === null ? 5 : performanceScore,
      accessibility: accessibilityScore,
      seo: seoScore,
      mobileResponsiveness: mobileResponsivenessScore,
      coreWebVitals: cwvScore
    },
    linksToCheck: uniqueLinks.slice(0, 15),
    cleanText,
    pageTitle: title
  }
}];

const links = $json.linksToCheck || [];
const results = await Promise.all(links.map(async (link) => {
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 6000);
    const res = await fetch(link, { method: 'HEAD', redirect: 'follow', signal: controller.signal });
    clearTimeout(timeout);
    return { link, ok: res.status < 400 };
  } catch (e) {
    return { link, ok: false };
  }
}));

const checked = results.length;
const broken = results.filter(r => !r.ok).length;
const brokenLinksScore = checked === 0 ? 5 : Math.round(((checked - broken) / checked) * 10);

return [{
  json: {
    ...$json,
    brokenLinksScore,
    brokenLinksChecked: checked,
    brokenLinksFound: broken
  }
}];

const parserData = $('Technical Audit Parser').item.json;
const brokenData = $('Broken Link Checker').item.json;
const aiRaw = $json;

let aiParsed;
try {
  // 1. Extract text regardless of which AI node structure was used
  let rawText = 
    aiRaw.text?.text || 
    aiRaw.text || 
    aiRaw.candidates?.[0]?.content?.parts?.[0]?.text || 
    aiRaw.choices?.[0]?.message?.content || 
    "";

  // 2. Strip out markdown code block wrappers (```json ... ```)
  rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

  // 3. Parse clean JSON
  aiParsed = JSON.parse(rawText);
} catch (e) {
  // Fallback only if JSON parsing fails
  aiParsed = { 
    scores: {}, 
    summary: 'AI scoring unavailable for this site.', 
    topRecommendations: [] 
  };
}

const tech = parserData.technicalScores;
const ai = aiParsed.scores || {};

function s(cat, fallback) {
  if (fallback === undefined) fallback = 5;
  return (ai[cat] && ai[cat].score !== undefined) ? ai[cat].score : fallback;
}

const allScores = {
  'Homepage Quality': s('homepageQuality'),
  'Navigation': s('navigation'),
  'User Experience': s('userExperience'),
  'Mobile Responsiveness': tech.mobileResponsiveness,
  'Website Speed': tech.websiteSpeed,
  'Performance': tech.performance,
  'SEO': tech.seo,
  'Accessibility': tech.accessibility,
  'Broken Links': brokenData.brokenLinksScore,
  'Security': tech.security,
  'SSL': tech.ssl,
  'Checkout Experience': s('checkoutExperience'),
  'Payment Options': tech.paymentOptions,
  'Search Functionality': s('searchAndFiltering', tech.searchFunctionality),
  'Filtering': s('searchAndFiltering', tech.searchFunctionality),
  'Product Pages': s('productPages'),
  'Image Quality': s('imageQuality'),
  'Content Quality': s('contentQuality'),
  'Trust Signals': s('trustSignals'),
  'Return Policy': tech.returnPolicy,
  'Privacy Policy': tech.privacyPolicy,
  'FAQ': tech.faq,
  'Live Chat': tech.liveChat,
  'Contact Information': tech.contactInformation,
  'Reviews': Math.round((s('reviews') + tech.reviewsTechnical) / 2),
  'Conversion Optimization': s('conversionAndCTAs'),
  'Call-To-Actions': s('conversionAndCTAs'),
  'Landing Pages': s('landingPages'),
  'Blog Activity': tech.blogActivity,
  'Technical SEO': tech.technicalSeo,
  'Schema Markup': tech.schemaMarkup,
  'Metadata': tech.metadata,
  'Internal Linking': tech.internalLinking,
  'Page Structure': tech.pageStructure,
  'Indexability': tech.indexability,
  'Core Web Vitals': tech.coreWebVitals
};

const values = Object.values(allScores).filter(v => typeof v === 'number');
const overallScore = Math.round((values.reduce((a,b) => a+b, 0) / values.length) * 10) / 10;

return [{
  json: {
    websiteUrl: parserData.websiteUrl,
    pageTitle: parserData.pageTitle,
    allScores,
    overallScore,
    summary: aiParsed.summary || 'Summary unavailable.',
    recommendations: aiParsed.topRecommendations || []
  }
}];

// Pull the score breakdown from "Merge All Scores" -- this node's own $json is
// the raw LLM output from Basic LLM Chain1, not the score data.
const scoreData = $('Merge All Scores').item.json;
const aiRaw = $json;

let analysis;
try {
  let rawText =
    aiRaw.text?.text ||
    aiRaw.text ||
    aiRaw.candidates?.[0]?.content?.parts?.[0]?.text ||
    aiRaw.choices?.[0]?.message?.content ||
    "";
  rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  analysis = JSON.parse(rawText);
} catch (e) {
  analysis = { categoryAnalysis: [], executiveSummary: 'Detailed analysis unavailable for this site.', outreachMessage: '' };
}

function statusColor(status) {
  switch (status) {
    case 'excellent': return '#1a7f37';
    case 'good': return '#2da44e';
    case 'needs_improvement': return '#b98600';
    case 'poor': return '#cf222e';
    case 'critical': return '#a40e26';
    default: return '#57606a';
  }
}

const categoryRows = (analysis.categoryAnalysis || []).map(function(c) {
  return '<tr>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;font-weight:600;">' + c.category + '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;text-align:center;">' +
      '<span style="background:' + statusColor(c.status) + ';color:#fff;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:600;">' + c.score + '/10</span>' +
    '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;font-size:12px;color:#333;">' + (c.whatIsLacking || '') + '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;font-size:12px;color:#333;">' + (c.actionableFix || '') + '</td>' +
  '</tr>';
}).join('');

const summaryParas = (analysis.executiveSummary || '')
  .split(/\n{2,}/).filter(Boolean)
  .map(function(p) { return '<p style="line-height:1.6;margin-bottom:14px;">' + p + '</p>'; })
  .join('');

const overallStatus = scoreData.overallScore >= 7 ? 'good' : scoreData.overallScore >= 4 ? 'needs_improvement' : 'poor';

const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><style>' +
  'body { font-family: Arial, Helvetica, sans-serif; color: #1f2328; margin: 0; padding: 40px; }' +
  'h1 { font-size: 24px; margin-bottom: 4px; }' +
  'h2 { font-size: 16px; margin-top: 32px; border-bottom: 2px solid #1f2328; padding-bottom: 6px; }' +
  '.sub { color: #57606a; margin-bottom: 20px; }' +
  '.overall { display:inline-block; background:' + statusColor(overallStatus) + '; color:#fff; padding:12px 24px; border-radius:8px; font-size:22px; font-weight:700; margin-bottom:20px; }' +
  'table { width:100%; border-collapse:collapse; font-size:13px; margin-top:12px; }' +
  'th { text-align:left; padding:10px; border-bottom:2px solid #1f2328; }' +
  '</style></head><body>' +
  '<h1>Website Technical Audit Report</h1>' +
  '<div class="sub">' + scoreData.websiteUrl + ' — ' + (scoreData.pageTitle || '') + '</div>' +
  '<div class="overall">Overall Score: ' + scoreData.overallScore + '/10</div>' +
  '<h2>Executive Summary</h2>' + summaryParas +
  '<h2>Category Breakdown</h2>' +
  '<table><tr><th>Category</th><th style="text-align:center;">Score</th><th>What\'s Lacking</th><th>Recommended Fix</th></tr>' +
  categoryRows + '</table>' +
  '</body></html>';

return [{
  json: {
    websiteUrl: scoreData.websiteUrl,
    pageTitle: scoreData.pageTitle,
    overallScore: scoreData.overallScore,
    summaryParas: summaryParas,
    categoryRows: categoryRows,
    outreachMessage: analysis.outreachMessage || ''
  }
}];

parameters.text:
=You are a website auditor scoring specific subjective categories from page content. 
Respond with ONLY a JSON object matching exactly this shape:
{
  "scores": {
    "homepageQuality": {"score": 5, "reason": "..."},
    "navigation": {"score": 5, "reason": "..."},
    "userExperience": {"score": 5, "reason": "..."},
    "checkoutExperience": {"score": 5, "reason": "..."},
    "searchAndFiltering": {"score": 5, "reason": "..."},
    "productPages": {"score": 5, "reason": "..."},
    "imageQuality": {"score": 5, "reason": "..."},
    "contentQuality": {"score": 5, "reason": "..."},
    "trustSignals": {"score": 5, "reason": "..."},
    "reviews": {"score": 5, "reason": "..."},
    "conversionAndCTAs": {"score": 5, "reason": "..."},
    "landingPages": {"score": 5, "reason": "..."}
  },
  "summary": "2-3 sentence overall summary",
  "topRecommendations": ["rec1", "rec2", "rec3"]
}

Website: {{ $json.websiteUrl }}
Page title: {{ $json.pageTitle }}

Technical signals already measured:
{{ JSON.stringify($json.technicalScores) }}

Page text extracted from the homepage:
{{ $json.cleanText }}
